"""Glob patterns."""
import re


def _brace_expand(p):
    i = 0
    while i < len(p):
        c = p[i]
        if c == "\\":
            i += 2
            continue
        if c == "{":
            j = i + 1
            alts = []
            cur = ""
            while True:
                if j >= len(p):
                    raise ValueError("unterminated {")
                d = p[j]
                if d == "\\":
                    cur += p[j:j + 2]
                    j += 2
                    continue
                if d == "{":
                    raise ValueError("nested {")
                if d == ",":
                    alts.append(cur)
                    cur = ""
                elif d == "}":
                    alts.append(cur)
                    break
                else:
                    cur += d
                j += 1
            rest = _brace_expand(p[j + 1:])
            return [p[:i] + a + r for a in alts for r in rest]
        i += 1
    return [p]


def _class(seg, i):
    """seg[i] == '['. Returns (regex, next index)."""
    j = i + 1
    negate = False
    if j < len(seg) and seg[j] in "!^":
        negate = True
        j += 1
    items = []
    while True:
        if j >= len(seg):
            raise ValueError("unterminated [")
        c = seg[j]
        if c == "]":
            break
        if c == "\\":
            if j + 1 >= len(seg):
                raise ValueError("backslash at the end")
            c = seg[j + 1]
            j += 1
        if j + 2 < len(seg) and seg[j + 1] == "-" and seg[j + 2] != "]":
            hi = seg[j + 2]
            if hi == "\\" and j + 3 < len(seg):
                hi = seg[j + 3]
                j += 1
            if hi < c:
                raise ValueError("backwards range")
            items.append("%s-%s" % (re.escape(c), re.escape(hi)))
            j += 3
        else:
            items.append(re.escape(c))
            j += 1
    if not items:
        raise ValueError("empty character class")
    return "(?!/)[%s%s]" % ("^" if negate else "", "".join(items)), j + 1


def _segment(seg):
    out = []
    i = 0
    while i < len(seg):
        c = seg[i]
        if c == "*":
            out.append("[^/]*")
        elif c == "?":
            out.append("[^/]")
        elif c == "[":
            rx, i = _class(seg, i)
            out.append(rx)
            continue
        elif c == "\\":
            if i + 1 >= len(seg):
                raise ValueError("backslash at the end")
            out.append(re.escape(seg[i + 1]))
            i += 1
        else:
            out.append(re.escape(c))
        i += 1
    return "".join(out)


def _to_regex(p):
    segs = p.split("/")
    out = []
    for idx, seg in enumerate(segs):
        last = idx == len(segs) - 1
        if seg == "**":
            out.append(".+" if last else "(?:[^/]+/)*")
        else:
            out.append(_segment(seg) + ("" if last else "/"))
    return "".join(out)


def match_glob(pattern, text):
    found = False
    for p in _brace_expand(pattern):
        if re.fullmatch(_to_regex(p), text):
            found = True
    return found

